<?php
namespace App\Models;use App\Casts\DateOnly;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides job budget behavior within the WorkIntel application. */ class JobBudget extends Model{protected $fillable=['uuid','workspace_id','project_id','cost_center_id','name','currency','labor_budget','expense_budget','procurement_budget','alert_threshold_percent','status','start_date','end_date','created_by'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['labor_budget'=>'decimal:2','expense_budget'=>'decimal:2','procurement_budget'=>'decimal:2','start_date'=>DateOnly::class,'end_date'=>DateOnly::class];}/** Handles the project operation for the current WorkIntel workflow. */ public function project():BelongsTo{return $this->belongsTo(Project::class);}}
